// src/pages/verifyEmail.jsx
// Where the "Confirm my email" button in Acalink's verification email lands
// (/verify-email?code=…). The link is generated by api/auth/otp.js from
// Firebase's own verification code, but points here instead of Firebase's
// generic handler page, so the whole journey looks like Acalink.
import { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { applyActionCode, checkActionCode } from "firebase/auth";
import { Check, MailWarning, Loader2 } from "lucide-react";
import { auth } from "../firebase";
import AuthLayout from "../components/auth/AuthLayout";

const FAILURES = {
  "auth/expired-action-code": "This link has expired. Sign in and send yourself a new one from your account settings.",
  "auth/invalid-action-code": "This link has already been used or isn't valid. If you've confirmed your email before, you're all set.",
  "auth/user-disabled": "This account has been deactivated. Contact your school administrator.",
  "auth/user-not-found": "We couldn't find the account this link was for.",
};

export default function VerifyEmail() {
  const [params] = useSearchParams();
  const code = params.get("code") || params.get("oobCode") || "";
  const [state, setState] = useState(code ? "working" : "failed");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState(code ? "" : "This link is incomplete. Open it straight from the email, or request a new one.");

  useEffect(() => {
    if (!code) return undefined;
    let alive = true;
    (async () => {
      try {
        const info = await checkActionCode(auth, code);
        if (alive) setEmail(info?.data?.email || "");
        await applyActionCode(auth, code);
        // A signed-in session caches the old "unverified" flag until reloaded.
        await auth.currentUser?.reload().catch(() => {});
        if (alive) setState("done");
      } catch (err) {
        if (!alive) return;
        setMessage(FAILURES[err.code] || "We couldn't confirm your email with this link. Please request a new one.");
        setState("failed");
      }
    })();
    return () => { alive = false; };
  }, [code]);

  return (
    <AuthLayout>
      <div className="la-card la-done">
        {state === "working" && (
          <>
            <span className="la-done__icon"><Loader2 size={28} className="spinner" /></span>
            <p className="lp-eyebrow">Email confirmation</p>
            <h1>Confirming your email…</h1>
            <p className="la-done__body">This only takes a moment.</p>
          </>
        )}

        {state === "done" && (
          <>
            <span className="la-done__icon"><Check size={30} strokeWidth={2.5} /></span>
            <p className="lp-eyebrow">Email confirmed</p>
            <h1>You&apos;re all set.</h1>
            <p className="la-done__body">
              {email ? <><strong>{email}</strong> is confirmed. </> : "Your email is confirmed. "}
              We&apos;ll use it to tell you when your school is approved, and for anything important about your account.
            </p>
            <div className="la-done__actions">
              <Link to="/signin" className="reg-btn reg-btn--primary">Sign in</Link>
            </div>
          </>
        )}

        {state === "failed" && (
          <>
            <span className="la-done__icon" style={{ background: "color-mix(in srgb, var(--lp-red) 14%, transparent)", color: "var(--lp-red)" }}>
              <MailWarning size={28} />
            </span>
            <p className="lp-eyebrow">Email confirmation</p>
            <h1>That link didn&apos;t work.</h1>
            <p className="la-done__body">{message}</p>
            <div className="la-done__actions">
              <Link to="/signin" className="reg-btn reg-btn--primary">Sign in</Link>
              <Link to="/" className="reg-btn reg-btn--ghost">Back to home</Link>
            </div>
          </>
        )}
      </div>
    </AuthLayout>
  );
}
